param()

$ErrorActionPreference = "Stop"

function Decode-Utf8([string]$Base64) {
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Base64))
}

function Read-Utf8([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Missing required file: $Path"
    }
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Write-Utf8([string]$Path, [string]$Content) {
    $Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Content, $Utf8NoBom)
}

function Insert-After-UniqueLine(
    [string]$Content,
    [string]$Anchor,
    [string]$NewLine,
    [string]$Label
) {
    if ($Content.Contains($NewLine)) {
        throw "${Label} already appears in the file"
    }

    $Pattern = [regex]::new(
        "(?m)^(?<indent>[ `t]*)" + [regex]::Escape($Anchor) + "[ `t]*$"
    )
    $Matches = $Pattern.Matches($Content)
    if ($Matches.Count -ne 1) {
        throw "Expected exactly one ${Label} anchor, found $($Matches.Count)"
    }

    $Newline = "`n"
    if ($Content.Contains("`r`n")) {
        $Newline = "`r`n"
    }

    return $Pattern.Replace(
        $Content,
        [System.Text.RegularExpressions.MatchEvaluator]{
            param($Match)
            return $Match.Value + $Newline + $Match.Groups["indent"].Value + $NewLine
        },
        1
    )
}

$RepoRoot = (Get-Location).Path

$HeaderPath = Join-Path $RepoRoot "src/relaycore/render/pipeline_authoring_overlay.h"
$SourcePath = Join-Path $RepoRoot "src/relaycore/render/pipeline_authoring_overlay.cpp"
$TestPath = Join-Path $RepoRoot "tests/pipeline_authoring_overlay_tests.cpp"
$SourceCMakePath = Join-Path $RepoRoot "src/relaycore/CMakeLists.txt"
$TestsCMakePath = Join-Path $RepoRoot "tests/CMakeLists.txt"
$DocPath = Join-Path $RepoRoot "docs/rc022g_pipeline_authoring_overlay.md"
$StatusPath = Join-Path $RepoRoot "STATUS.md"

foreach ($NewPath in @($HeaderPath, $SourcePath, $TestPath, $DocPath)) {
    if (Test-Path -LiteralPath $NewPath) {
        throw "File already exists: $NewPath"
    }
}

$SourceCMake = Read-Utf8 $SourceCMakePath
$TestsCMake = Read-Utf8 $TestsCMakePath
$Status = Read-Utf8 $StatusPath

$SourceCMakeUpdated = Insert-After-UniqueLine `
    $SourceCMake `
    'render/render_authoring_config.cpp' `
    'render/pipeline_authoring_overlay.cpp' `
    'source CMake implementation'

$SourceCMakeUpdated = Insert-After-UniqueLine `
    $SourceCMakeUpdated `
    'render/render_authoring_config.h' `
    'render/pipeline_authoring_overlay.h' `
    'source CMake header'

$TestsCMakeUpdated = Insert-After-UniqueLine `
    $TestsCMake `
    'render_authoring_config_tests.cpp' `
    'pipeline_authoring_overlay_tests.cpp' `
    'tests CMake entry'

$StatusPattern = [regex]::new("(?m)^RC-022g[^\r\n]*$")
$StatusMatches = $StatusPattern.Matches($Status)
if ($StatusMatches.Count -ne 1) {
    throw "Expected exactly one open RC-022g line in STATUS.md, found $($StatusMatches.Count)"
}
$StatusReplacement = Decode-Utf8 ""
$StatusUpdated = $StatusPattern.Replace($Status, $StatusReplacement, 1)

Write-Utf8 $HeaderPath (Decode-Utf8 "")
Write-Utf8 $SourcePath (Decode-Utf8 "")
Write-Utf8 $TestPath (Decode-Utf8 "")
Write-Utf8 $DocPath (Decode-Utf8 "")
Write-Utf8 $SourceCMakePath $SourceCMakeUpdated
Write-Utf8 $TestsCMakePath $TestsCMakeUpdated
Write-Utf8 $StatusPath $StatusUpdated

Write-Host "Applied RC-022g iteration 1."
Write-Host "Added:"
Write-Host "  src/relaycore/render/pipeline_authoring_overlay.h"
Write-Host "  src/relaycore/render/pipeline_authoring_overlay.cpp"
Write-Host "  tests/pipeline_authoring_overlay_tests.cpp"
Write-Host "  docs/rc022g_pipeline_authoring_overlay.md"
Write-Host "Updated:"
Write-Host "  src/relaycore/CMakeLists.txt"
Write-Host "  tests/CMakeLists.txt"
Write-Host "  STATUS.md"
Write-Host ""
Write-Host "Next:"
Write-Host "  git diff --check"
Write-Host "  cmake --build --preset tests-debug --parallel 1"
Write-Host "  ctest --preset test-debug --output-on-failure"
